with j as (select * from jsonb_to_recordset($law7d0053$[{"code_id":"NK_RF","article_number":"11.3","version_date":"2000-07-31","article_text":"1. Единым налоговым платежом признаются денежные средства, перечисленные налогоплательщиком, плательщиком сбора, плательщиком страховых взносов, налоговым агентом и (или) иным лицом в бюджетную систему Российской Федерации на счет Федерального казначейства, предназначенные для исполнения совокупной обязанности налогоплательщика, плательщика сбора, плательщика страховых взносов, налогового агента, а также денежные средства, взысканные с налогоплательщика, плательщика сбора, плательщика страховых взносов и (или) налогового агента в соответствии с настоящим Кодексом. Для целей настоящего Кодекса единым налоговым платежом также признаются суммы денежных средств, подлежащие учету на едином налоговом счете:\n\n1) в связи с принятием налоговым органом решения о возмещении (о предоставлении налогового вычета) суммы налога, - в день принятия соответствующего решения;\n\n2) в связи с поступлением от иного лица в результате зачета суммы денежных средств в соответствии со статьей 78 настоящего Кодекса, - в день осуществления налоговым органом такого зачета;\n\n3) в связи с отменой (полностью или частично) зачета денежных средств в счет исполнения предстоящей обязанности по уплате конкретного налога (сбора, страхового взноса) на основании заявления, представленного в соответствии с пунктом 6 статьи 78 настоящего Кодекса, либо в связи с представлением налогоплательщиком - физическим лицом заявления о перерасчете суммы ранее исчисленного налога или жалобы на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении, либо в связи с отсутствием на едином налоговом счете денежных средств, необходимых для исполнения обязанности по уплате налогов, сборов, страховых взносов, пеней, штрафов и (или) процентов, - не позднее дня, следующего за днем представления указанного заявления в соответствии с пунктом 6 статьи 78 настоящего Кодекса, или дня, следующего за днем представления налогоплательщиком - физическим лицом заявления о перерасчете суммы ранее исчисленного налога или данной жалобы,, или в день возникновения задолженности. Признание единым налоговым платежом сумм денежных средств, ранее зачтенных в счет исполнения предстоящей обязанности налогоплательщика, плательщика сбора, плательщика страховых взносов и (или) налогового агента по уплате конкретного налога, осуществляется последовательно начиная с наиболее ранних сроков уплаты налога (сбора, страхового взноса), в счет исполнения обязанности по уплате которого был осуществлен зачет. В случае совпадения сроков уплаты признание единым налоговым платежом указанных денежных средств осуществляется начиная с меньшей суммы; (В редакции  федеральных законов от 29.05.2023 № 196-ФЗ, от 31.07.2023 № 389-ФЗ, от 31.07.2025 № 287-ФЗ)\n\n4) в связи с начислением налоговым органом процентов в соответствии с пунктами 4 и (или) 9 статьи 79 настоящего Кодекса, - со дня их начисления;\n\n5) в связи с представлением налогоплательщиком, плательщиком сбора, плательщиком страховых взносов заявления о возврате излишне уплаченных сумм налога на доходы физических лиц, уплачиваемого в порядке, установленном статьей 2271 настоящего Кодекса, налога на профессиональный доход и сборов за пользование объектами животного мира и за пользование объектами водных биологических ресурсов, налога на сверхприбыль,  страховых взносов на дополнительное социальное обеспечение членов летных экипажей воздушных судов гражданской авиации, а также отдельных категорий работников организаций угольной промышленности, - в размере излишне уплаченной суммы налога (сбора, страхового взноса) не позднее дня, следующего за днем получения указанного заявления. Перечни указанных в настоящем подпункте плательщиков страховых взносов устанавливаются в порядке, предусмотренном соответственно Федеральным законом от 27 ноября 2001 года № 155-ФЗ \"О дополнительном социальном обеспечении членов летных экипажей воздушных судов гражданской авиации\" и Федеральным законом от 10 мая 2010 года № 84-ФЗ \"О дополнительном социальном обеспечении отдельных категорий работников организаций угольной промышленности\". (В редакции  федеральных законов от 08.08.2024 № 259-ФЗ, от 29.10.2024 № 362-ФЗ)\n\n2. Единым налоговым счетом признается форма учета налоговыми органами:\n\n1) денежного выражения совокупной обязанности;\n\n2) денежных средств, перечисленных в качестве единого налогового платежа и (или) признаваемых в качестве единого налогового платежа.\n\n3. Сальдо единого налогового счета представляет собой разницу между общей суммой денежных средств, перечисленных и (или) признаваемых в качестве единого налогового платежа, и денежным выражением совокупной обязанности.\n\nПоложительное сальдо единого налогового счета формируется, если общая сумма денежных средств, перечисленных и (или) признаваемых в качестве единого налогового платежа, больше денежного выражения совокупной обязанности. При формировании положительного сальдо единого налогового счета не учитываются суммы денежных средств, зачтенные в счет исполнения соответствующей обязанности налогоплательщика, плательщика сбора, плательщика страховых взносов и (или) налогового агента. (В редакции  Федерального закона от 29.05.2023 № 196-ФЗ)\n\nОтрицательное сальдо единого налогового счета формируется, если общая сумма денежных средств, перечисленных и (или) признаваемых в качестве единого налогового платежа, меньше денежного выражения совокупной обязанности.\n\nНулевое сальдо единого налогового счета формируется, если общая сумма денежных средств, перечисленных и (или) признаваемых в качестве единого налогового платежа, равна денежному выражению совокупной обязанности.\n\n4. Единый налоговый счет ведется в отношении каждого физического лица и каждой организации, являющихся налогоплательщиками, плательщиками сборов, плательщиками страховых взносов и (или) налоговыми агентами (в том числе при исполнении обязанности управляющего товарища, ответственного за ведение налогового учета в связи с выполнением договора инвестиционного товарищества).\n\n5. Совокупная обязанность формируется и подлежит учету на едином налоговом счете лица, указанного в пункте 4 настоящей статьи, в валюте Российской Федерации на основе:\n\n1) налоговых деклараций (расчетов), которые представлены в налоговый орган (за исключением налоговых деклараций (расчетов) указанных в подпункте 3 настоящего пункта), - со дня их представления в налоговый орган, но не ранее наступления срока уплаты соответствующих налогов (сборов, авансовых платежей по налогам, страховых взносов), если иное не предусмотрено абзацем вторым настоящего подпункта.\n\nВ случае обнаружения налоговым органом факта несоответствия показателей указанных в абзаце первом настоящего подпункта налоговых деклараций (расчетов) (за исключением налоговых деклараций (расчетов), представленных налогоплательщиками, в отношении которых проводится налоговый мониторинг) контрольным соотношениям, свидетельствующего о нарушении порядка их заполнения (за исключением контрольных соотношений, указанных в пункте 53 статьи 174 настоящего Кодекса), указанные налоговые декларации (расчеты) учитываются при определении размера совокупной обязанности со дня вступления в силу решения налогового органа по результатам камеральной налоговой проверки на основе указанных налоговых деклараций (расчетов) либо в течение десяти дней со дня окончания установленного статьей 88 настоящего Кодекса срока проведения камеральной налоговой проверки или со дня, сл\n\nедующего за днем завершения камеральной налоговой проверки указанных налоговых деклараций (расчетов), если при ее проведении не были выявлены нарушения законодательства о налогах и сборах.\n\nПеречень контрольных соотношений, указанных в абзаце втором настоящего подпункта, утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов;\n\n(Подпункт в редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n2) уточненных налоговых деклараций (расчетов), которые представлены в налоговый орган и в которых по сравнению с ранее представленными в налоговые органы налоговыми декларациями (расчетами) увеличены причитающиеся к уплате суммы налогов (сборов, авансовых платежей по налогам, страховых взносов), - со дня представления в налоговые органы уточненных налоговых деклараций (расчетов), но не ранее наступления срока уплаты соответствующих налогов (сборов, авансовых платежей по налогам, страховых взносов);\n\n3) налоговых деклараций, в которых заявлены суммы налогов к возмещению либо суммы предусмотренных главой 23 настоящего Кодекса налоговых вычетов, - со дня вступления в силу решения налогового органа по результатам камеральной налоговой проверки на основе указанных налоговых деклараций (расчетов) либо в течение десяти дней со дня окончания установленного статьей 88 настоящего Кодекса срока проведения камеральной налоговой проверки указанных налоговых деклараций (расчетов) или со дня, следующего за днем завершения камеральной налоговой проверки указанных налоговых деклараций (расчетов), если при проведении камеральной налоговой проверки указанной налоговой декларации не были выявлены нарушения законодательства о налогах и сборах, если иное не предусмотрено настоящим пунктом; (В редакции  федеральных законов от 28.12.2022 № 565-ФЗ, от 31.07.2023 № 389-ФЗ)\n\n31) уточненных налоговых деклараций (расчетов) (за исключением уточненных налоговых деклараций (расчетов), указанных в подпункте 4 настоящего пункта), в которых по сравнению с ранее представленными в налоговые органы налоговыми декларациями (расчетами) уменьшены причитающиеся к уплате суммы налогов (сборов, авансовых платежей по налогам, страховых взносов):\n\nв случае их представления не позднее наступления срока уплаты соответствующих налогов (сборов, авансовых платежей по налогам, страховых взносов) - со дня их представления, но не ранее наступления срока уплаты соответствующих налогов (сборов, авансовых платежей по налогам, страховых взносов);\n\nв случае их представления после наступления срока уплаты соответствующих налогов (сборов, авансовых платежей по налогам, страховых взносов) - со дня вступления в силу решения налогового органа по результатам камеральной налоговой проверки на основе указанных налоговых деклараций (расчетов), либо в течение десяти дней со дня окончания установленного статьей 88 настоящего Кодекса срока проведения камеральной налоговой проверки указанных налоговых деклараций (расчетов) или со дня, следующего за днем завершения камеральной налоговой проверки указанных налоговых деклараций (расчетов), если при ее проведении не были выявлены нарушения законодательства о налогах и сборах, либо со дня их представления, если в течение следующего рабочего дня после представления уточненных налоговых деклараций (расчетов), указанных в абзаце первом настоящего подпункта, представлены уточненные декларации (расчеты), в которых по сравнению с ранее представленными уточненными налоговыми декларациями (расчетами) увеличены причитающиеся к уплате суммы налогов (сборов, авансовых платежей по налогам, страховых взносов) в размере, равном суммам налогов (сборов, авансовых платежей по налогам, страховых взносов), на которые они были уменьшены в уточненных налоговых декларациях (расчетах), указанных в абзаце первом настоящего подпункта; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 28.12.2022 № 565-ФЗ)\n\n4) уточненных налоговых деклараций (расчетов), которые представлены организацией, в отношении которой проводится налоговый мониторинг, и в которых по сравнению с ранее представленными в налоговые органы налоговыми декларациями (расчетами) уменьшены причитающиеся к уплате суммы налогов (сборов, авансовых платежей по налогам, страховых взносов), со дня представления в налоговый орган уточненных налоговых деклараций (расчетов), но не ранее наступления срока уплаты соответствующих налогов (сборов, авансовых платежей по налогам, страховых взносов); (В редакции  Федерального закона от 28.12.2022 № 565-ФЗ)\n\n5) уведомлений об исчисленных суммах налогов, сборов, авансовых платежей по налогам, страховых взносов, представленных в налоговый орган, - со дня представления в налоговый орган таких уведомлений, но не ранее наступления срока уплаты соответствующих налогов, сборов, авансовых платежей по налогам, страховых взносов и до дня, с которого подлежит учету совокупная обязанность на основе налоговой декларации (расчета) по соответствующим налогам, сборам, авансовым платежам по налогам, страховым взносам, указанным в уведомлении, или до дня, с которого совокупная обязанность формируется и подлежит учету на едином налоговом счете на основе сообщений об исчисленных налоговым органом суммах налогов; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n6) налоговых уведомлений - со дня наступления установленного законодательством о налогах и сборах срока уплаты соответствующего налога; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n7) сообщений об исчисленных налоговым органом суммах налогов - со дня, следующего за днем информирования налоговым органом налогоплательщика-организации (ее обособленного подразделения) о результатах рассмотрения пояснений и (или) документов, представленных в налоговый орган в соответствии с пунктом 6 статьи 363, пунктом 6 статьи 386, пунктом 5 статьи 397 настоящего Кодекса, либо со дня, следующего за днем истечения одного месяца, в случае непредставления таких пояснений и (или) документов;\n\n8) вступивших в силу решений налогового органа о предоставлении отсрочки, рассрочки по уплате налогов, сборов, страховых взносов, пеней, штрафов и (или) процентов в соответствии с главой 9 настоящего Кодекса - со дня, указанного в соответствующем решении; (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n9) решений налогового органа о привлечении к ответственности за совершение налоговых правонарушений, решений налоговых органов об отказе в привлечении к ответственности за совершение налоговых правонарушений, решений об отмене (полностью или частично) решений о возмещении суммы налога, заявленной к возмещению, в заявительном порядке, решений об отмене (полностью или частично) решений о предоставлении налогового вычета полностью или частично, решений, вынесенных по результатам проверки федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, полноты исчисления и уплаты налогов в связи с совершением сделок между взаимозависимыми лицами, - со дня вступления в силу соответствующего решения, если иное не предусмотрено подпунктами 10 и 101 настоящего пункта; (В редакции  федеральных законов от 08.08.2024 № 259-ФЗ, от 31.07.2025 № 287-ФЗ)\n\n10) решений налогового органа о привлечении к ответственности за совершение налоговых правонарушений, решений налоговых органов об отказе в привлечении к ответственности за совершение налоговых правонарушений, решений об отмене (полностью или частично) решений о возмещении суммы налога, заявленной к возмещению, в заявительном порядке, решений об отмене (полностью или частично) решений о предоставлении налогового вычета, которыми установлено неисполнение обязанности по уплате налога в связи с изменением налоговым органом юридической квалификации сделки, совершенной налогоплательщиком, или статуса и характера деятельности налогоплательщика, - со дня вступления в силу соответствующего судебного акта; (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n101) решения о привлечении к ответственности за совершение налогового правонарушения (решения об отказе в привлечении к ответственности за совершение налогового правонарушения), вынесенного налоговым органом в отношении физического лица, не являющегося индивидуальным предпринимателем, на которое указанным физическим лицом подана апелляционная жалоба, - со дня вступления в законную силу судебного акта о взыскании задолженности; (Дополнение подпунктом - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\n11) судебного акта или решения вышестоящего налогового органа, отменяющего (изменяющего) судебный акт или решение налогового органа, на основании которых на едином налоговом счете ранее была учтена обязанность лица по уплате сумм налогов, авансовых платежей по налогам, сборов, страховых взносов, пеней, штрафов и (или) процентов, - на дату вступления в законную силу соответствующего судебного акта или решения;\n\n12) исполнительных документов о взыскании с лица, указанного в пункте 4 настоящей статьи, государственной пошлины - со дня выдачи судом соответствующего исполнительного документа, который для целей учета совокупной обязанности на едином налоговом счете признается установленным сроком уплаты;\n\n13) расчетов суммы налога (перерасчета ранее исчисленных сумм налога), произведенных налоговым органом в соответствии с Федеральным законом от 25 февраля 2022 года № 17-ФЗ \"О проведении эксперимента по установлению специального налогового режима \"Автоматизированная упрощенная система налогообложения\" или в соответствии с Федеральным законом от 27 ноября 2018 года № 422-ФЗ \"О проведении эксперимента по установлению специального налогового режима \"Налог на профессиональный доход\", - со дня уведомления налогоплательщика о сумме налога, подлежащего уплате, но не ранее наступления срока уплаты соответствующих налогов;\n\n14) сведений о разрешениях, выданных органами, выдающими в установленном порядке разрешения на добычу объектов животного мира и (или) разрешения на добычу (вылов) водных биологических ресурсов, - со дня представления сведений указанными органами;\n\n15) решения о признании задолженности безнадежной к взысканию и ее списании - со дня принятия соответствующего решения;\n\n16) уведомлений, представленных плательщиком торгового сбора в налоговый орган в соответствии со статьей 416 настоящего Кодекса, информации уполномоченного органа, представленной в налоговый орган в соответствии с пунктом 4 статьи 418 настоящего Кодекса, - со дня представления в налоговый орган указанных уведомлений, информации;\n\n17) иных документов, предусматривающих возникновение, изменение, прекращение обязанности по уплате налогов, сборов, страховых взносов, пеней, штрафов и (или) процентов, установленной законодательством о налогах и сборах, - не ранее наступления срока уплаты соответствующих налогов, сборов, страховых взносов, пеней, штрафов, процентов. (В редакции  Федерального закона от 28.12.2022 № 565-ФЗ)\n\n6. Сумма пеней, рассчитанная в соответствии со статьей 75 настоящего Кодекса, учитывается в совокупной обязанности со дня учета на едином налоговом счете недоимки, в отношении которой рассчитана данная сумма.\n\nСумма процентов, определяемая в соответствии со статьей 64 настоящего Кодекса, учитывается в совокупной обязанности со дня, следующего за днем уплаты последнего платежа, предусмотренного решением о предоставлении отсрочки, рассрочки, если иное не предусмотрено настоящим пунктом.\n\nВ случае представления налогоплательщиком заявления о досрочном исполнении решения о предоставлении отсрочки, рассрочки в соответствии с главой 9 настоящего Кодекса либо заявления в соответствии с абзацем третьим пункта 4 статьи 78 настоящего Кодекса сумма задолженности, в отношении которой поданы такие заявления, учитывается в совокупной обязанности последовательно начиная с задолженности с наиболее ранним сроком уплаты в размере, не превышающем положительное сальдо единого налогового счета на дату ее учета, со дня, следующего за днем представления заявления.\n\n7. При определении размера совокупной обязанности не учитываются:\n\n1) суммы налогов, сборов, страховых взносов, подлежащих уменьшению на основании налоговых деклараций (расчетов), уточненных налоговых деклараций (расчетов), предусматривающих уменьшение подлежащих уплате сумм налогов, сборов, страховых взносов, если со дня истечения установленного законодательством о налогах и сборах срока уплаты соответствующих налога, сбора, страховых взносов до дня подачи указанных налоговых деклараций (расчетов), уточненных налоговых деклараций (расчетов) прошло более трех лет, за исключением случаев осуществления налоговым органом перерасчета налогов, сборов, страховых взносов по основаниям, предусмотренным настоящим Кодексом, и случаев восстановления судом указанного срока, если причины его пропуска признаны судом уважительными; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n2) суммы налогов, государственной пошлины, в отношении уплаты которой арбитражным судом выдан исполнительный документ, иных сборов, страховых взносов, пеней, штрафов, процентов, по которым истек срок их взыскания, до даты вступления в законную силу судебного акта о восстановлении пропущенного срока либо судебного акта о взыскании таких сумм; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n3) суммы налогов, сборов, страховых взносов, пеней, штрафов, процентов, указанных в вынесенном налоговым органом решении о привлечении к ответственности за совершение налогового правонарушения или решении об отказе в привлечении к ответственности за совершение налогового правонарушения, если судом были приняты меры предварительной защиты (обеспечительные меры), в соответствии с которыми приостановлено полностью или в части действие такого оспариваемого решения налогового органа, либо если вышестоящим налоговым органом было принято решение о приостановлении исполнения такого решения о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения, - до дня вступления в законную силу судебного акта об отмене (замене) указанных мер предварительной защиты (обеспечительных мер) либо до дня принятия вышестоящим налоговым органом решения по соответствующей жалобе, повлекших прекращение приостановления полностью или в части действия решения налогового органа о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения;\n\n31) обжалуемые суммы налогов, сборов, страховых взносов, пеней, штрафов, процентов, указанные в решении о привлечении к ответственности за совершение налогового правонарушения (решении об отказе в привлечении к ответственности за совершение налогового правонарушения), вынесенном налоговым органом в отношении физического лица, не являющегося индивидуальным предпринимателем, в решении об отмене (полностью или частично) решения о предоставлении налогового вычета полностью или частично, обязанность по уплате которых не исполнена по состоянию на дату получения налоговым органом жалобы, - с даты получения налоговым органом такой жалобы до даты вступления в законную силу судебного акта о взыскании таких сумм; (Дополнение подпунктом - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\n32) оспариваемые суммы налогов, указанные в налоговом уведомлении, обязанность по уплате которых не исполнена по состоянию на дату получения налоговым органом представленного налогоплательщиком - физическим лицом заявления о перерасчете суммы ранее исчисленного налога, - с даты получения налоговым органом такого заявления до истечения тридцати дней со дня формирования налоговым органом сообщения об отказе в перерасчете суммы ранее исчисленного налога по такому заявлению (если в течение указанного тридцатидневного срока не была подана жалоба в отношении сумм налогов, указанных в налоговом уведомлении) или до даты вступления в законную силу судебного акта о взыскании этих сумм (если данная жалоба была подана в течение указанного тридцатидневного срока).\n\nПоложения настоящего подпункта не применяются, если в отношении соответствующей суммы налога, указанной в налоговом уведомлении, налогоплательщиком - физическим лицом ранее было представлено заявление о перерасчете суммы ранее исчисленного налога и (или) была рассмотрена жалоба такого налогоплательщика - физического лица и по ней было принято решение, предусмотренное пунктом 3 статьи 140 настоящего Кодекса;\n\n(Дополнение подпунктом - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\n33) обжалуемые суммы налогов, указанные в налоговом уведомлении, обязанность по уплате которых не исполнена по состоянию на дату получения налоговым органом жалобы налогоплательщика - физического лица на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении, - с даты получения налоговым органом данной жалобы до истечения тридцати дней со дня принятия решения вышестоящего налогового органа об оставлении жалобы на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении, без удовлетворения (если в течение указанного тридцатидневного срока налогоплательщиком - физическим лицом не было представлено уведомление о несогласии с решением вышестоящего налогового органа по данной жалобе), или до даты вступления в законную силу судебного акта о взыскании таких сумм (если в течение указанного тридцатидневного срока налогоплательщиком - физическим лицом такое уведомление было представлено), или до даты принятия решения об оставлении жалобы без рассмотрения.\n\nПоложения настоящего подпункта не применяются, если в отношении соответствующей суммы налога, указанной в налоговом уведомлении, ранее была рассмотрена жалоба налогоплательщика - физического лица и по данной жалобе было принято решение, предусмотренное пунктом 3 статьи 140 настоящего Кодекса, и (или) таким налогоплательщиком - физическим лицом было представлено заявление о перерасчете суммы ранее исчисленного налога;\n\n(Дополнение подпунктом - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\n34) обжалуемые суммы налогов, сборов, страховых взносов, пеней, штрафов, процентов, указанные в решении о привлечении к ответственности за совершение налогового правонарушения (решении об отказе в привлечении к ответственности за совершение налогового правонарушения), вынесенном налоговым органом в отношении физического лица, не являющегося индивидуальным предпринимателем, в решении об отмене (полностью или частично) решения о предоставлении налогового вычета полностью или частично, и (или) суммы налогов, указанные в налоговом уведомлении, в отношении которых отсутствует судебный акт о взыскании, если налогоплательщиком - физическим лицом была подана жалоба на требование об уплате задолженности или на решение о взыскании задолженности, в размере не более суммы отрицательного сальдо единого налогового счета такого физического лица на дату получения налоговым органом данной жалобы - с даты получения налоговым органом данной жалобы до истечения пятнадцати дней со дня принятия налоговым органом решения по соответствующей жалобе; (Дополнение подпунктом - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\n4) уплаченные налогоплательщиком (плательщиком сборов, плательщиком страховых взносов) не в качестве единого налогового платежа суммы налога на профессиональный доход, сборов за пользование объектами животного мира и за пользование объектами водных биологических ресурсов, налога на сверхприбыль,   страховых взносов на дополнительное социальное обеспечение членов летных экипажей воздушных судов гражданской авиации, а также отдельных категорий работников организаций угольной промышленности. Перечни указанных в настоящем подпункте плательщиков страховых взносов устанавливаются в порядке, предусмотренном соответственно Федеральным законом от 27 нояб\n\nря 2001 года № 155-ФЗ \"О дополнительном социальном обеспечении членов летных экипажей воздушных судов гражданской авиации\" и Федеральным законом от 10 мая 2010 года № 84-ФЗ \"О дополнительном социальном обеспечении отдельных категорий работников организаций угольной промышленности\"; (В редакции  федеральных законов от 08.08.2024 № 259-ФЗ, от 29.10.2024 № 362-ФЗ)\n\n5) суммы налогов, сборов, страховых взносов, пеней, штрафов, процентов, по которым принято решение о временном (на период рассмотрения заявления о предоставлении отсрочки или рассрочки) приостановлении уплаты суммы задолженности в соответствии со статьей 64 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 28.12.2022 № 565-ФЗ)\n\n6) суммы налогов, государственной пошлины, в отношении уплаты которых арбитражным судом выдан исполнительный документ, иных сборов, страховых взносов, пеней, штрафов, процентов в иных случаях, предусмотренных законодательством Российской Федерации о налогах и сборах. (Дополнение подпунктом - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 14.07.2022 № 263-ФЗ)","article_title":"Статья 11.3. Единый налоговый платеж. Единый налоговый счет","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cc5557b12401022d23c95578052d3f17106417ea6e19496c9be896d251ea93ff"},{"code_id":"NK_RF","article_number":"113","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n1. Лицо не может быть привлечено к ответственности за совершение налогового правонарушения, если со дня его совершения либо со следующего дня после окончания налогового (расчетного) периода, в течение которого было совершено это правонарушение, и до момента вынесения решения о привлечении к ответственности истекли три года (срок давности). (В редакции федеральных законов о\n\nИсчисление срока давности со дня совершения налогового правонарушения применяется в отношении всех налоговых правонарушений, кроме предусмотренных статьями 120, 122, 1293 и 1295 настоящего Кодекса. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nИсчисление срока давности со следующего дня после окончания соответствующего налогового периода применяется в отношении налоговых правонарушений, предусмотренных статьями 120, 122, 1293 и 1295 настоящего Кодекса. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nТечение срока давности привлечения к ответственности считается приостановленным со дня составления акта, предусмотренного пунктом 3 статьи 91 настоящего Кодекса. В этом случае течение срока давности привлечения к ответственности возобновляется со дня, когда прекратили действие обстоятельства, препятствующие проведению выездной налоговой проверки, и вынесено решение о возобновлении выездной налоговой проверки.\n\n(Дополнение пунктом - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\n2. (Пункт исключен - Федеральный закон от 09.07.1999 № 154-ФЗ)","article_title":"Статья 113. Срок давности привлечения к ответственности за совершение налогового правонарушения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"279a54ce3a31f907bca4b84b924bb16575a66c1621bf4895a4221f5333788198"},{"code_id":"NK_RF","article_number":"114","version_date":"2000-07-31","article_text":"1. Налоговая санкция является мерой ответственности за совершение налогового правонарушения.","article_title":"Статья 114. Налоговые санкции","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"72c90a136e9a8ca943f04ffc1ac3cc6fb3eccfe25fd8949d33e74527d0245df4"},{"code_id":"NK_RF","article_number":"115","version_date":"2000-07-31","article_text":"(Статья утратила силу  - Федеральный закон от 14.07.2022 № 263-ФЗ)","article_title":"Статья 115. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0760e08016882ad16f11f2560e12e965f879cb6ecc2ddffa5db2aa47ff1da8b6"},{"code_id":"NK_RF","article_number":"116","version_date":"2000-07-31","article_text":"1. Нарушение налогоплательщиком установленного настоящим Кодексом срока подачи заявления о постановке на учет в налоговом органе по основаниям, предусмотренным настоящим Кодексом,\n\nвлечет взыскание штрафа в размере 10 тысяч рублей.\n\n2. Ведение деятельности организацией или индивидуальным предпринимателем без постановки на учет в налоговом органе по основаниям, предусмотренным настоящим Кодексом,\n\nвлечет взыскание штрафа в размере 10 процентов от доходов, полученных в течение указанного времени в результате такой деятельности, но не менее 40 тысяч рублей.\n\n(Статья в редакции Федерального закона от 27.07.2010 № 229-ФЗ)","article_title":"Статья 116. Нарушение порядка постановки на учет в налоговом органе","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"208f1e3fabd66978df222e0d3ae27689ea0bb4951ae7cea396bc34e0b6604a3d"},{"code_id":"NK_RF","article_number":"117","version_date":"2000-07-31","article_text":"(Статья утратила силу - Федеральный закон от 27.07.2010 № 229-ФЗ)","article_title":"Статья 117. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a63b4d25bb84290a5e35497b79db01d71b1135d6ac4ee2810b4bd9a8f1ccc81b"},{"code_id":"NK_RF","article_number":"118","version_date":"2000-07-31","article_text":"(Статья утратила силу - Федеральный закон от 02.04.2014 № 52-ФЗ)","article_title":"Статья 118. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"817aa4a29b87f49a3c1b32407aedf3a4b03e196aab8af67dfd055b5f571b5549"},{"code_id":"NK_RF","article_number":"119","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 28.11.2011 № 336-ФЗ; от 03.07.2016 № 243-ФЗ)\n\n1. Непредставление в установленный законодательством о налогах и сборах срок налоговой декларации (расчета по страховым взносам) в налоговый орган по месту учета, расчета сумм выплаченных иностранным организациям доходов и удержанных налогов за прошедший отчетный (налоговый) период в налоговый орган по месту нахождения налогового агента\n\nвлечет взыскание штрафа в размере 5 процентов не уплаченной (не перечисленной) в установленный законодательством о налогах и сборах срок суммы налога (страховых взносов), подлежащей уплате (доплате, перечислению) на основании данной налоговой декларации (расчета), за каждый полный или неполный месяц со дня, установленного для ее представления, но не более 30 процентов указанной суммы и не менее 1000 рублей.\n\n(Пункт в редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n2. Непредставление управляющим товарищем, ответственным за ведение налогового учета, расчета финансового результата инвестиционного товарищества в налоговый орган по месту учета в установленный законодательством о налогах и сборах срок\n\nвлечет взыскание штрафа в размере 1 000 рублей за каждый полный или неполный месяц со дня, установленного для его представления.\n\n(Дополнение пунктом - Федеральный закон от 28.11.2011 № 336-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2010 № 229-ФЗ)","article_title":"Статья 119. Непредставление налоговой декларации (расчета финансового результата инвестиционного товарищества, расчета по страховым взносам)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bbc4f84083c10fe7bf7df7dbce40047295064bb96af4b48286a0ee697025a254"},{"code_id":"NK_RF","article_number":"119.1","version_date":"2000-07-31","article_text":"Несоблюдение порядка представления налоговой декларации (расчета) в электронной форме в случаях, предусмотренных настоящим Кодексом, (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\nвлечет взыскание штрафа в размере 200 рублей.\n\n(Дополнение статьей - Федеральный закон от 27.07.2010 № 229-ФЗ)","article_title":"Статья 119.1. Нарушение установленного способа представления налоговой декларации (расчета)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7793a67c15712aea8da0733135dd9df8ac64848b27eebaad02d7f47a055316b7"},{"code_id":"NK_RF","article_number":"119.2","version_date":"2000-07-31","article_text":"1. Представление в налоговый орган управляющим товарищем, ответственным за ведение налогового учета, расчета финансового результата инвестиционного товарищества, содержащего недостоверные сведения,\n\nвлечет взыскание штрафа в размере сорока тысяч рублей.\n\n2. Те же деяния, совершенные умышленно,\n\nвлекут взыскание штрафа в размере восьмидесяти тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 28.11.2011 № 336-ФЗ)","article_title":"Статья 119.2. Представление в налоговый орган управляющим товарищем, ответственным за ведение налогового учета, расчета финансового результата инвестиционного товарищества, содержащего недостоверные сведения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e202ec49a8bba8b5412e56a42385a4981764ed12959362d8d50a034820559427"},{"code_id":"NK_RF","article_number":"12","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 11.06.2021 № 199-ФЗ, от 08.08.2024 № 259-ФЗ)\n\n1. В Российской Федерации устанавливаются следующие виды налогов и сборов: федеральные, региональные и местные.\n\nРегиональные налоги вводятся в действие и прекращают действовать на территориях субъектов Российской Федерации в соответствии с настоящим Кодексом и законами субъектов Российской Федерации о налогах, если иное не предусмотрено настоящим пунктом. (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\nПри установлении региональных налогов законодательными органами субъектов Российской Федерации определяются в порядке и пределах, которые предусмотрены настоящим Кодексом, следующие элементы налогообложения: налоговые ставки, порядок и сроки уплаты налогов, если эти элементы налогообложения не установлены настоящим Кодексом. Иные элементы налогообложения по региональным налогам и налогоплательщики определяются настоящим Кодексом. (В редакции  федеральных законов от 27.07.2010 № 229-ФЗ, от 08.08.2024 № 259-ФЗ)\n\nЗаконодательными органами субъектов Российской Федерации законами о налогах в порядке и пределах, которые предусмотрены настоящим Кодексом, могут устанавливаться особенности определения налоговой базы, налоговые льготы, основания и порядок их применения. (В редакции  федеральных законов от 02.11.2013 № 307-ФЗ, от 08.08.2024 № 259-ФЗ)\n\nРегиональные налоги, обязательные к уплате в федеральной территории \"Сириус\", устанавливаются, вводятся в действие и прекращают действовать в указанной территории в соответствии с настоящим Кодексом. Представительным органом федеральной территории \"Сириус\" в порядке и пределах, которые предусмотрены настоящим Кодексом, могут устанавливаться налоговые льготы, основания и порядок их применения. (Дополнение абзацем - Федеральный закон от 11.06.2021 № 199-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nМестные налоги и сборы вводятся в действие и прекращают действовать на территориях муниципальных образований в соответствии с настоящим Кодексом и нормативными правовыми актами представительных органов муниципальных образований о налогах и сборах, если иное не предусмотрено настоящим пунктом. (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\nМестные налоги и сборы устанавливаются настоящим Кодексом и нормативными правовыми актами представительных органов поселений (муниципальных районов), муниципальных округов, городских округов (внутригородских районов) о налогах и сборах и обязательны к уплате на территориях соответствующих поселений (межселенных территориях), муниципальных округов, городских округов (внутригородских районов), если иное не предусмотрено пунктом 7 настоящей статьи. Местные налоги и сборы вводятся в действие и прекращают действовать на территориях поселений (межселенных территориях), муниципальных округов, городских округов (внутригородских районов) в соответствии с настоящим Кодексом и нормативными правовыми актами представительных органов поселений (муниципальных районов), муниципальных округов, городских округов (внутригородских районов) о налогах и сборах. (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\nВ городском округе с внутригородским делением полномочия представительных органов муниципальных образований по установлению, введению в действие и прекращению действия местных налогов на территориях внутригородских районов осуществляются представительными органами городского округа с внутригородским делением либо представительными органами соответствующих внутригородских районов согласно закону субъекта Российской Федерации о разграничении полномочий между органами местного самоуправления городского округа с внутригородским делением и органами местного самоуправления внутригородских районов.\n\nМестные налоги и сборы в городах федерального значения Москве, Санкт-Петербурге и Севастополе устанавливаются настоящим Кодексом и законами указанных субъектов Российской Федерации о налогах и сборах, обязательны к уплате на территориях этих субъектов Российской Федерации, если иное не предусмотрено пунктом 7 настоящей статьи. Местные налоги и сборы вводятся в действие и прекращают действовать на территориях городов федерального значения Москвы, Санкт-Петербурга и Севастополя в соответствии с настоящим Кодексом и законами указанных субъектов Российской Федерации.\n\nМестные налоги и сборы в федеральной территории \"Сириус\" устанавливаются настоящим Кодексом и нормативными правовыми актами представительного органа федеральной территории \"Сириус\" о местных налогах и сборах и обязательны к уплате в указанной территории, если иное не предусмотрено пунктом 7 настоящей статьи. Местные налоги и сборы вводятся в действие и прекращают действовать в федеральной территории \"Сириус\" в соответствии с настоящим Кодексом и нормативными правовыми актами представительного органа федеральной территории \"Сириус\" о местных налогах и сборах. (Дополнение абзацем - Федеральный закон от 11.06.2021 № 199-ФЗ)\n\nПри установлении местных налогов представительными органами муниципальных образований (законодательными (представительными) органами государственной власти городов федерального значения Москвы, Санкт-Петербурга и Севастополя, представительным органом федеральной территории \"Сириус\") определяются в порядке и пределах, которые предусмотрены настоящим Кодексом, следующие элементы налогообложения: налоговые ставки, порядок и сроки уплаты налогов, если эти элементы налогообложения не установлены настоящим Кодексом. Иные элементы налогообложения по местным налогам и налогоплательщики определяются настоящим Кодексом. (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\nПредставительными органами муниципальных образований (законодательными (представительными) органами государственной власти городов федерального значения Москвы, Санкт-Петербурга и Севастополя, представительным органом федеральной территории \"Сириус\") в порядке и пределах, которые предусмотрены настоящим Кодексом, могут устанавливаться особенности определения налоговой базы, налоговые льготы, основания и порядок их применения. (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\nПри установлении местных сборов представительными органами муниципальных образований (законодательными (представительными) органами государственной власти городов федерального значения Москвы, Санкт-Петербурга и Севастополя, представительным органом федеральной территории \"Сириус\") определяются в порядке и пределах, которые предусмотрены настоящим Кодексом, ставки сборов, а также могут устанавливаться льготы по уплате сборов, основания и порядок их применения. (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\n(Пункт в редакции Федерального закона от 29.11.2014 № 382-ФЗ)\n\nСпециальные налоговые режимы могут предусматривать освобождение от обязанности по уплате отдельных федеральных, региональных и местных налогов и сборов, указанных в статьях 13 - 15 настоящего Кодекса.\n\nЗаконодательные органы субъектов Российской Федерации и представительные органы муниципальных образований в случаях, порядке и пределах, которые предусмотрены настоящим Кодексом, вправе устанавливать по специальным налоговым режимам: (Дополнение абзацем - Федеральный закон от 13.07.2015 № 232-ФЗ) (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nвиды предпринимательской деятельности, в отношении которых может применяться соответствующий специальный налоговый режим; (Дополнение абзацем - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\nограничения на переход на специальный налоговый режим и на применение специального налогового режима; (Дополнение абзацем - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\nналоговые ставки в зависимости от категорий налогоплательщиков и видов предпринимательской деятельности; (Дополнение абзацем - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\nособенности определения налоговой базы; (Дополнение абзацем - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\nналоговые льготы, а также основания и порядок их применения. (Дополнение абзацем - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\n(Статья в редакции Федерального закона от 29.07.2004 № 95-ФЗ)","article_title":"Статья 12. Виды налогов и сборов в Российской Федерации. Полномочия законодательных органов субъектов Российской Федерации, представительных органов муниципальных образований, представительного органа федеральной территории \"Сириус\" по установлению налогов и сборов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"08f4dd9dc15c143ca7e1aa2dc4046c736f9bc85f6cf67c7d3e52c104a3ab7ab3"},{"code_id":"NK_RF","article_number":"120","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nвлечет взыскание штрафа в размере десяти тысяч рублей. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nвлекут взыскание штрафа в размере тридцати тысяч рублей. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nвлекут взыскание штрафа в размере двадцати процентов от суммы неуплаченного налога (страховых взносов), но не менее сорока тысяч рублей. (В редакции федеральных законов от 27.07.2010 № 229-ФЗ; от 03.07.2016 № 243-ФЗ)\n\nПод грубым нарушением правил учета доходов и расходов и объектов налогообложения для целей настоящей статьи понимается отсутствие первичных документов, или отсутствие счетов-фактур, или регистров бухгалтерского учета или налогового учета, систематическое (два раза и более в течение календарного года) несвоевременное или неправильное отражение на счетах бухгалтерского учета, в регистрах налогового учета и в отчетности хозяйственных операций, денежных средств, материальных ценностей, нематериальных активов и финансовых вложений. (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 27.07.2010 № 229-ФЗ; от 23.07.2013 № 248-ФЗ)","article_title":"Статья 120. Грубое нарушение правил учета доходов и расходов и объектов налогообложения (базы для исчисления страховых взносов)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e43d8c04ca44a2fbf422088aea9de698abb4bb00094195bb5380ad52b2a390ee"},{"code_id":"NK_RF","article_number":"121","version_date":"2000-07-31","article_text":"(Статья исключена - Федеральный закон от 09.07.1999 № 154-ФЗ)","article_title":"Статья 121. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eae2ab0dd7a6c8944f2c6b85e6302d187e64cbff9e97fe9c4271b2d8c4098eca"},{"code_id":"NK_RF","article_number":"122","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 27.07.2006 № 137-ФЗ; от 03.07.2016 № 243-ФЗ)\n\nвлечет взыскание штрафа в размере 20 процентов от неуплаченной суммы налога (сбора, страховых взносов). (В редакции федеральных законов от 27.07.2006 № 137-ФЗ; от 03.07.2016 № 243-ФЗ)\n\nвлекут взыскание штрафа в размере 40 процентов от неуплаченной суммы налога (сбора, страховых взносов). (В редакции федеральных законов от 27.07.2006 № 137-ФЗ; от 03.07.2016 № 243-ФЗ)","article_title":"Статья 122. Неуплата или неполная уплата сумм налога (сбора, страховых взносов)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b631aac9d1d989d5d425c405b98b53d497e8627edcd649a7b188af1206a8c6c3"},{"code_id":"NK_RF","article_number":"122.1","version_date":"2000-07-31","article_text":"1. Сообщение участником консолидированной группы налогоплательщиков ответственному участнику этой группы недостоверных данных (несообщение данных), приведшее к неуплате или неполной уплате налога на прибыль организаций по консолидированной группе налогоплательщиков ее ответственным участником, влечет взыскание штрафа в размере 20 процентов от неуплаченной суммы налога.\n\n2. Деяния, предусмотренные пунктом 1 настоящей статьи, совершенные умышленно, влекут взыскание штрафа в размере 40 процентов от неуплаченной суммы налога.\n\n(Дополнение статьей - Федеральный закон от 16.11.2011 № 321-ФЗ)","article_title":"Статья 122.1. Сообщение участником консолидированной группы налогоплательщиков ответственному участнику этой группы недостоверных данных (несообщение данных), приведшее к неуплате или неполной уплате налога на прибыль организаций ответственным участником","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"86a8692dab9ef661afe2f269e4ee80b6089c8b558788ffdd72dff209e1d0e320"},{"code_id":"NK_RF","article_number":"123","version_date":"2000-07-31","article_text":"влечет взыскание штрафа в размере 20 процентов от суммы, подлежащей удержанию и (или) перечислению. (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 27.07.2010 № 229-ФЗ)\n\nналоговый расчет (расчет по налогу) представлен в налоговый орган в установленный срок;\n\nв налоговом расчете (расчете по налогу) отсутствуют факты неотражения или неполноты отражения сведений и (или) ошибки, приводящие к занижению суммы налога, подлежащей перечислению в бюджетную систему Российской Федерации;\n\nналоговым агентом исполнена обязанность по перечислению суммы налога до момента, когда ему стало известно об обнаружении налоговым органом факта несвоевременного перечисления суммы налога или о назначении выездной налоговой проверки по такому налогу за соответствующий налоговый период. (В редакции  федеральных законов от 14.07.2022 № 263-ФЗ, от 28.12.2022 № 565-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 27.12.2018 № 546-ФЗ)","article_title":"Статья 123. Невыполнение налоговым агентом обязанности по удержанию и (или) перечислению налогов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"593dcacb8bab6cc9cb9d13b95c64232913024a1e817ea5a4f32f0f96218c5118"},{"code_id":"NK_RF","article_number":"124","version_date":"2000-07-31","article_text":"(Статья утратила силу - Федеральный закон от 30.12.2001 № 196-ФЗ)","article_title":"Статья 124. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cc4ce31e87bfcb0ccac499eed86987b89e67aee9c4cb7fe6607cab50b562b415"},{"code_id":"NK_RF","article_number":"125","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 27.07.2010 № 229-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nНесоблюдение установленного настоящим Кодексом порядка владения, пользования и (или) распоряжения имуществом, на которое наложен арест или в отношении которого налоговым органом приняты обеспечительные меры в виде залога либо в виде запрета на отчуждение (передачу в залог) имущества лица без согласия налогового органа, (В редакции  федеральных законов от 09.07.1999 № 154-ФЗ, от 27.07.2010 № 229-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nвлечет взыскание штрафа в размере 30 тысяч рублей. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)","article_title":"Статья 125. Несоблюдение порядка владения, пользования и (или) распоряжения имуществом, на которое наложен арест или в отношении которого налоговым органом приняты обеспечительные меры в виде залога либо в виде запрета на отчуждение (передачу в залог) имущества лица без согласия налогового органа","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0232d13a423d2533639ab045247c67ddd4d5d74b68aacad932a94d3261b700f3"},{"code_id":"NK_RF","article_number":"126","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\nвлечет взыскание штрафа в размере 200 рублей за каждый непредставленный документ. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 09.07.1999 № 154-ФЗ)\n\n11. Непредставление налоговому органу документов, подтверждающих размер прибыли (убытка) контролируемой иностранной компании, в срок, установленный пунктом 5 статьи 2515 настоящего Кодекса, либо представление таких документов с заведомо недостоверными сведениями\n\nвлечет взыскание штрафа с контролирующего лица в размере 500 000 рублей.\n\n(Дополнение пунктом - Федеральный закон от 24.11.2014 № 376-ФЗ) (В редакции Федерального закона от 09.11.2020 № 368-ФЗ)\n\n11-1. Непредставление налоговому органу документов, истребуемых в соответствии с пунктом 1 статьи 2514-1 настоящего Кодекса, в срок, установленный пунктом 2 статьи 2514-1 настоящего Кодекса, либо представление таких документов с заведомо недостоверными сведениями\n\nвлечет взыскание штрафа с контролирующего лица в размере 1 миллиона рублей.\n\n(Дополнение пунктом - Федеральный закон от 09.11.2020 № 368-ФЗ)\n\n12. Непредставление налоговым агентом в установленный срок расчета сумм налога на доходы физических лиц, исчисленных и удержанных налоговым агентом, в налоговый орган по месту учета\n\nвлечет взыскание штрафа с налогового агента в размере 1 000 рублей за каждый полный или неполный месяц со дня, установленного для его представления.\n\n(Дополнение пунктом - Федеральный закон от 02.05.2015 № 113-ФЗ)\n\nвлечет взыскание штрафа с организации или индивидуального предпринимателя в размере десяти тысяч рублей, с физического лица, не являющегося индивидуальным предпринимателем, - в размере одной тысячи рублей. (В редакции Федерального закона от 23.07.2013 № 248-ФЗ)\n\n1) в отношении налогоплательщика, являющегося контролирующим лицом указанной иностранной компании, действовали введенные иностранными государствами, экономическими, политическими, военными или иными объединениями стран, международными финансовыми и иными организациями запретительные, ограничительные и (или) иные аналогичные меры, заключающиеся в установлении запретов и (или) ограничений на предоставление такому налогоплательщику в отношении указанной иностранной компании документов, предусмотренных подпунктом 1 пункта 5 статьи 2515 настоящего Кодекса;\n\n2) постоянным местонахождением указанной иностранной компании являлось иностранное государство, включенное в соответствии с законодательством Российской Федерации в перечень иностранных государств и территорий, совершающих в отношении Российской Федерации, российских юридических и физических лиц недружественные действия.\n\n(Дополнение пунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)","article_title":"Статья 126. Непредставление налоговому органу сведений, необходимых для осуществления налогового контроля","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eddb13ebe97f16eba1a0e56faa7a36efa98cfead6c8bac59f82d0575d21cb438"},{"code_id":"NK_RF","article_number":"126.1","version_date":"2000-07-31","article_text":"у документов, содержащих недостоверные сведения\n\nвлечет взыскание штрафа в размере 500 рублей за каждый представленный документ, содержащий недостоверные сведения.\n\n(Дополнение статьей - Федеральный закон от 02.05.2015 № 113-ФЗ)","article_title":"Статья 126.1. Представление налоговым агентом налоговому орган","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e1283e26c9d38fe3c3e246509e35d42644f421010999f561703c85e385f8ab5b"},{"code_id":"NK_RF","article_number":"126.2","version_date":"2000-07-31","article_text":"1. Представление налоговым агентом и (или) негосударственным пенсионным фондом налоговому органу недостоверных сведений о факте открытия индивидуального инвестиционного счета налогоплательщика, о факте заключения договора негосударственного пенсионного обеспечения и (или) договора долгосрочных сбережений, о суммах денежных средств, внесенных налогоплательщиком на такой индивидуальный инвестиционный счет за соответствующий налоговый период, о суммах фактических взносов налогоплательщика по договору негосударственного пенсионного обеспечения, договору долгосрочных сбережений в рамках процедуры получения налогоплательщиком инвестиционных налоговых вычетов и (или) налоговых вычетов на долгосрочные сбережения граждан в порядке, установленном статьей 2211 настоящего Кодекса,\n\nвлечет взыскание штрафа в размере 20 процентов от суммы налога, неправомерно полученного налогоплательщиком в связи с предоставлением инвестиционного налогового вычета и (или) налогового вычета на долгосрочные сбережения граждан в упрощенном порядке на основании представленных налоговым агентом и (или) негосударственным пенсионным фондом недостоверных сведений.\n\n2. Налоговый агент и (или) негосударственный пенсионный фонд освобождаются от ответственности, предусмотренной пунктом 1 настоящей статьи, в случае, если ими самостоятельно выявлены ошибки и уточненные сведения представлены налоговому органу до момента, когда налоговый агент и (или) негосударственный пенсионный фонд узнали об обнаружении налоговым органом недостоверности представленных налоговым агентом и (или) негосударственным пенсионным фондом сведений.\n\n(Дополнение статьей - Федеральный закон от 20.04.2021 № 100-ФЗ) (В редакции  Федерального закона от 23.03.2024 № 58-ФЗ)","article_title":"Статья 126.2. Представление налоговым агентом и (или) негосударственным пенсионным фондом налоговому органу недостоверных сведений в рамках процедуры получения налогоплательщиками инвестиционных налоговых вычетов и (или) налоговых вычетов на долгосрочные сбережения граждан в упрощенном порядке","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e0c6335416633bbdbebed6636465166044beba686995922b3f8845b792176c03"},{"code_id":"NK_RF","article_number":"126.3","version_date":"2000-07-31","article_text":"1. Представление организациями и индивидуальными предпринимателями, указанными в абзаце первом пункта 31 статьи 2211 настоящего Кодекса, налоговому органу недостоверных сведений о фактических произведенных налогоплательщиком расходах за оказанные услуги, содержащихся в документах, указанных в абзаце четвертом подпункта 2, абзацах восьмом и десятом подпункта 3, абзаце втором подпункта 4 и абзаце девятом подпункта 7 пункта 1 статьи 219 настоящего Кодекса, в рамках процедуры получения налогоплательщиком социальных налоговых вычетов в порядке, установленном статьей 2211 настоящего Кодекса,\n\nвлечет взыскание штрафа в размере 20 процентов от суммы налога, неправомерно полученного налогоплательщиком в связи с предоставлением социального налогового вычета в упрощенном порядке на основании представленных организациями и индивидуальными предпринимателями недостоверных сведений.\n\n2. Организации и индивидуальные предприниматели освобождаются от ответственности, предусмотренной пунктом 1 настоящей статьи, в случае, если ими самостоятельно выявлены ошибки и уточненные документы, указанные в абзаце четвертом подпункта 2, абзацах восьмом и десятом подпункта 3, абзаце втором подпункта 4 и абзаце девятом подпункта 7 пункта 1 статьи 219 настоящего Кодекса, представлены налоговому органу до момента, когда соответствующие организации и индивидуальные предприниматели узнали об обнаружении налоговым органом недостоверности представленных сведений.\n\n(Дополнение статьей - Федеральный закон от 31.07.2023 № 389-ФЗ)","article_title":"Статья 126.3. Представление организациями (индивидуальными предпринимателями) налоговому органу недостоверных сведений для целей получения налогоплательщиками социальных налоговых вычетов в упрощенном порядке","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cd45ee2d86efe542501b5ee8bdec8a9f68315927456a2a2e32d8b9de2ede51db"},{"code_id":"NK_RF","article_number":"127","version_date":"2000-07-31","article_text":"(Статья исключена - Федеральный закон от 09.07.1999 № 154-ФЗ)","article_title":"Статья 127. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eae2ab0dd7a6c8944f2c6b85e6302d187e64cbff9e97fe9c4271b2d8c4098eca"},{"code_id":"NK_RF","article_number":"128","version_date":"2000-07-31","article_text":"Неявка либо уклонение от явки без уважительных причин лица, вызываемого по делу о налоговом правонарушении в качестве свидетеля,\n\nвлечет взыскание штрафа в размере тысячи рублей. (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\nНеправомерный отказ свидетеля от дачи показаний, а равно дача заведомо ложных показаний (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\nвлечет взыскание штрафа в размере трех тысяч рублей. (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 128. Ответственность свидетеля","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a9f76889437825b75c894733a29a4403c17fb6514f7f38b503bd2fcbba4068d2"},{"code_id":"NK_RF","article_number":"129","version_date":"2000-07-31","article_text":"влечет взыскание штрафа в размере 500 рублей.\n\nвлечет взыскание штрафа в размере 5000 рублей. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)","article_title":"Статья 129. Отказ эксперта, переводчика или специалиста от участия в проведении налоговой проверки, дача заведомо ложного заключения или осуществление заведомо ложного перевода","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5cdb299b7f14caf171c6f788f15ab08bf4b8ec09ccc2a1e5d3e5c35164b31cc8"},{"code_id":"NK_RF","article_number":"129.1","version_date":"2000-07-31","article_text":"влечет взыскание штрафа в размере 5000 рублей. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nвлекут взыскание штрафа в размере 20000 рублей. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nвлечет взыскание штрафа в размере 50 000 рублей.\n\n(Дополнение пунктом - Федеральный закон от 24.11.2014 № 376-ФЗ) (В редакции Федерального закона от 20.04.2021 № 100-ФЗ)\n\nвлечет взыскание штрафа в размере 20 процентов от неуплаченной суммы налога в отношении объекта недвижимого имущества и (или) транспортного средства, по которым не представлено (несвоевременно представлено) сообщение, предусмотренное пунктами 21 и 22 статьи 23 настоящего Кодекса. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 02.04.2014 № 52-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 09.07.1999 № 154-ФЗ)","article_title":"Статья 129.1. Неправомерное несообщение сведений налоговому органу","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0dac129d2f6c33bad7d188184a6b220aba51af9c02fa3efed41a293e4373d43b"},{"code_id":"NK_RF","article_number":"129.10","version_date":"2000-07-31","article_text":"Неправомерное непредставление в установленный срок странового отчета или представление странового отчета, содержащего недостоверные сведения,\n\nвлечет взыскание штрафа в размере 1 000 000 рублей. (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 27.11.2017 № 340-ФЗ)","article_title":"Статья 129.10. Непредставление странового отчета, представление странового отчета, содержащего недостоверные сведения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4a2b77bab6968c36be1d52ef96ad14d038757e4cfe7364c1d56f148fae135173"},{"code_id":"NK_RF","article_number":"129.11","version_date":"2000-07-31","article_text":"ельщика страховых взносов или налогового агента, но не более суммы задолженности, а при отсутствии задолженности - в размере 20 тысяч рублей. (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nвлечет взыскание штрафа в размере одной стопятидесятой ставки рефинансирования Центрального банка Российской Федерации, но не более 0,2 процента за каждый календарный день просрочки.\n\nвлечет взыскание штрафа в размере 30 процентов не поступившей в результате таких действий суммы.\n\nвлекут взыскание штрафа в размере 10 тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 27.06.2011 № 162-ФЗ)","article_title":"Статья 129.11. Непредставление документации в отношении  международной группы компаний,  документации относительно конкретной сделки  (группы однородных сделок), непредставление сведений (представление недостоверных сведений) из консолидированной финансовой отчетности международной группы компаний, финансовой отчетности участника международной группы компаний","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b4aa2e8c6261e9a20f3d8a33fccbc06026f957201e5216f0362d44349172f776"},{"code_id":"NK_RF","article_number":"129.2","version_date":"2000-07-31","article_text":"влечет взыскание штрафа в трехкратном размере ставки налога на игорный бизнес, установленной для соответствующего объекта налогообложения.\n\nвлекут взыскание штрафа в шестикратном размере ставки налога на игорный бизнес, установленной для соответствующего объекта налогообложения.\n\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 137-ФЗ)","article_title":"Статья 129.2. Нарушение порядка регистрации объектов игорного бизнеса","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"84f226beb122e516ccd895b6863191d37874cd9f63dd33486c9ae899f694c944"},{"code_id":"NK_RF","article_number":"129.3","version_date":"2000-07-31","article_text":"влечет взыскание штрафа в размере неуплаченной суммы налога с дохода, указанного в абзаце первом пункта 61 статьи 1053 настоящего Кодекса, но не менее 500 000 рублей. (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\n12. Неуплата или неполная уплата налогоплательщиком сумм налога в результате применения в целях налогообложения в сделках, признаваемых контролируемыми сделками в соответствии с пунктом 2 статьи 10514 настоящего Кодекса, коммерческих и (или) финансовых условий, не сопоставимых с коммерческими и (или) финансовыми условиями сделок между лицами, не являющимися взаимозависимыми,\n\nвлечет взыскание штрафа в размере 40 процентов от неуплаченной суммы налога, но не менее 30 000 рублей.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 18.07.2011 № 227-ФЗ)","article_title":"Статья 129.3. Неуплата или неполная уплата сумм налога в результате применения в целях налогообложения в контролируемых сделках коммерческих и (или) финансовых условий, не сопоставимых с коммерческими и (или) финансовыми условиями сделок между лицами, не являющимися взаимозависимыми","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"afab4ed55a0f23788ddab1e5e2c6a9d383ad739c496d7da261f17d23c87a6fdf"},{"code_id":"NK_RF","article_number":"129.4","version_date":"2000-07-31","article_text":"Неправомерное непредставление в установленный срок налогоплательщиком в налоговый орган уведомления о контролируемых сделках, совершенных в календарном году, или представление налогоплательщиком в налоговый орган уведомления о контролируемых сделках, содержащего недостоверные сведения,\n\nвлечет взыскание штрафа в размере 100 000 рублей. (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 18.07.2011 № 227-ФЗ)","article_title":"Статья 129.4. Неправомерное непредставление уведомления о контролируемых сделках, представление недостоверных сведений в уведомлении о контролируемых сделках","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"75ccd69ae3ad544fc68d588b67276f77e9726fd6db4eb77339b8242e82762def"}]$law7d0053$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
